free.css:
.f-stage { display: grid; align-content: center; gap: var(--cs-gap); padding: var(--cs-unit); block-size: 100%; }
.f-big { font-family: var(--cs-font-display); font-size: var(--cs-fs-title); line-height: 1.35; }
.f-tail { font-size: var(--cs-fs-h); }
.f-pin { display: flex; align-items: center; justify-content: space-between; gap: var(--cs-gap); }

.f-page { display: grid; align-content: start; gap: var(--cs-gap); padding: var(--cs-unit); }
.f-head { display: flex; align-items: center; gap: var(--cs-gap); }
.f-num { display: flex; align-items: center; justify-content: center; min-inline-size: 150px; min-block-size: 150px; padding: 12px; border-radius: 75px; font-family: var(--cs-font-display); font-size: var(--cs-fs-title); }
.f-title { font-family: var(--cs-font-heading); font-size: var(--cs-fs-title); line-height: 1.3; color: var(--cs-ink); }
.f-text { font-size: var(--cs-fs-body); line-height: 1.6; color: var(--cs-ink); }
.f-ico { justify-self: end; }

.f-page { display: grid; align-content: start; gap: var(--cs-gap); padding: var(--cs-unit); }
.f-title { font-family: var(--cs-font-heading); font-size: var(--cs-fs-title); line-height: 1.3; color: var(--cs-ink); }
.f-text { font-size: var(--cs-fs-body); line-height: 1.6; color: var(--cs-ink-muted); }
.f-chat { display: grid; gap: 20px; padding: 28px; border-radius: 32px; background-color: var(--cs-surface); }
.f-chat p { max-inline-size: 80%; padding: 20px 28px; font-size: var(--cs-fs-body); line-height: 1.5; border-radius: 28px; }
.f-cap { font-size: var(--cs-fs-small); color: var(--cs-ink-muted); }

.f-page { display: grid; align-content: start; gap: var(--cs-gap); padding: var(--cs-unit); }
.f-title { font-family: var(--cs-font-heading); font-size: var(--cs-fs-title); line-height: 1.3; color: var(--cs-ink); }
.f-list { display: grid; gap: 28px; }
.f-row { display: flex; align-items: center; gap: 28px; padding: 24px 32px; border-radius: 28px; background-color: var(--cs-surface); font-size: var(--cs-fs-body); line-height: 1.5; color: var(--cs-ink); }
.f-row:first-child { background: linear-gradient(135deg, var(--cs-surface), var(--cs-bg)); }
.f-prize { justify-self: end; }
